        return
    if target.path == "/v1/proof-check-proof-verifications":
        self._get_proof_check_proof_verifications(target.query)
        return
    if target.path == "/v1/final-audit-proofs":
        self._get_final_audit_proofs(target.query)
        return
    final_chain_item_match = (
        FINAL_AUDIT_PROOF_CHAIN_ITEM_PATH_PATTERN.fullmatch(target.path)
    )
    if final_chain_item_match is not None:
        self._get_final_audit_proof_chain_item(
            final_chain_item_match.group(1), target.query
        )
        return
    if target.path == "/v1/final-audit-proof-chain":
        self._get_final_audit_proof_chain(target.query)
        return
    if target.path == "/v1/final-audit-proof-witnesses":
        self._get_final_audit_proof_witnesses(target.query)
        return
    if target.path == "/v1/final-audit-proof-verifications":
        self._get_final_audit_proof_verifications(target.query)
        return
    if target.path == "/v1/final-audit-verification-proofs":
        self._get_final_audit_verification_proofs(target.query)
        return
    final_verification_chain_item_match = (
        FINAL_AUDIT_VERIFICATION_PROOF_CHAIN_ITEM_PATH_PATTERN.fullmatch(
            target.path
